def get_text(lang: str, key: str, **kwargs) -> str:
    lang = lang if lang in TEXTS else "tr"
    value = TEXTS[lang].get(key, TEXTS["tr"].get(key, key))
    try:
        return value.format(**kwargs)
    except (KeyError, ValueError):
        return value

