def get_role_text(lang: str, role: str) -> tuple[str, str]:
    lang = lang if lang in ROLE_TRANSLATIONS else "tr"
    return ROLE_TRANSLATIONS[lang].get(role, ROLE_TRANSLATIONS["tr"].get(role, (role, "")))
